const html = String($input.first().json.html ?? $input.first().json.data ?? "");
const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, " ");

const moneyMatches = [...text.matchAll(/\$([\d,]+)\s+pledged/gi)];
const backerMatches = [...text.matchAll(/([\d,]+)\s+backers/gi)];
const goalMatch = text.match(/pledged\s+of\s+\$([\d,]+)/i);

if (!moneyMatches.length || !backerMatches.length) {
  throw new Error("Could not parse Kickstarter pledged/backer totals from public campaign page.");
}

const pledged = Number(moneyMatches[0][1].replace(/,/g, ""));
const backers = Number(backerMatches[0][1].replace(/,/g, ""));
const goal = goalMatch ? Number(goalMatch[1].replace(/,/g, "")) : 10000;
const now = new Date();
const date = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Australia/Perth",
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
}).format(now);
const end = new Date("2026-11-19T16:57:00.000Z");
const daysRemaining = Math.max(0, Math.ceil((end.getTime() - now.getTime()) / 86400000));
const dimensions = {
  campaign: "magic-and-mayhem",
  campaign_label: "Fable Fury — Magic & Mayhem",
  campaign_status: daysRemaining > 0 ? "live" : "finished",
  campaign_start: "2026-10-20",
  campaign_end: "2026-11-19"
};

return [{
  json: {
    source: { key: "kickstarter", type: "crowdfunding", displayName: "Kickstarter" },
    run: {
      key: `kickstarter-live-${date}`,
      status: "success",
      startedAt: now.toISOString(),
      finishedAt: now.toISOString(),
      rowsRead: 4,
      rowsWritten: 4,
      rowsFailed: 0
    },
    metrics: [
      { date, metric: "campaign_pledged", dimensionKey: "magic-and-mayhem", dimensions, value: pledged, unit: "USD", sourceUpdatedAt: now.toISOString() },
      { date, metric: "campaign_backers", dimensionKey: "magic-and-mayhem", dimensions, value: backers, unit: "count", sourceUpdatedAt: now.toISOString() },
      { date, metric: "campaign_goal", dimensionKey: "magic-and-mayhem", dimensions, value: goal, unit: "USD", sourceUpdatedAt: now.toISOString() },
      { date, metric: "campaign_days_remaining", dimensionKey: "magic-and-mayhem", dimensions, value: daysRemaining, unit: "days", sourceUpdatedAt: now.toISOString() }
    ],
    products: [],
    inventory: [],
    records: []
  }
}];
